/**
 * The app. ForgeKit's `ForgeHost` opens one per process and keeps it.
 */
public protocol AppCoreProtocol: AnyObject, Sendable {
    
    /**
     * Adds this iPhone at `location_id` as a WireGuard device named
     * `device_name`, and returns its config for the WireGuard app.
     */
    func addThisIphone(locationId: String, deviceName: String) async throws  -> WireguardConfig
    
    /**
     * The host's background time ran out: finishing work stops.
     */
    func backgroundTimeExpired() 
    
    /**
     * Whether commands or finishing work are still running; the
     * host holds background time while they are.
     */
    func backgroundWorkPending()  -> Bool
    
    /**
     * The config of a device already on the account, to send to WireGuard
     * again (for example on a new iPhone).
     */
    func configFor(connectionId: String) async throws  -> WireguardConfig
    
    /**
     * The runtime's event stream: `Changed { revision }` after each
     * committed command, phase changes, and drops. Nil after shutdown.
     */
    func events()  -> RuntimeEvents?
    
    /**
     * What the screens show. Quick: it never waits for a command.
     */
    func home()  -> Home
    
    /**
     * What the runtime found at open (unfinished background work).
     */
    func launchReport()  -> LaunchReport
    
    /**
     * Loads the server locations the customer can pick from.
     */
    func loadLocations() async throws  -> Home
    
    /**
     * The phase last reported.
     */
    func phase()  -> AppPhase
    
    /**
     * Reloads the plan and devices from the server.
     */
    func refresh() async throws  -> Home
    
    /**
     * Removes a device from the account; its WireGuard config stops working.
     */
    func removeConnection(connectionId: String) async throws  -> Home
    
    /**
     * The last committed revision.
     */
    func revision()  -> UInt64
    
    /**
     * The host reports the application lifecycle phase.
     */
    func setPhase(phase: AppPhase) 
    
    /**
     * Refuses new commands, stops work in flight and ends event
     * streams. Commands already accepted still finish and save.
     */
    func shutdown() 
    
    /**
     * Signs in with an email or username and password, keeps the session
     * in the Keychain, and loads the plan and devices.
     */
    func signIn(server: String, login: String, password: String) async throws  -> Home
    
    /**
     * Signs out here and on the server. Always ends signed out, even
     * offline: the server session then expires on its own.
     */
    func signOut() async throws  -> Home
    
    /**
     * A random trip for `criteria`. Keep `seed` for one "Surprise me" and
     * change `rolls` or `locks` to re-roll or keep sections.
     */
    func randomTrip(criteria: TripCriteria, seed: String, rolls: TripRolls, locks: TripLocks) async throws  -> RandomTrip
    
    /**
     * Deletes a saved trip.
     */
    func deleteTrip(tripId: String) async throws  -> Home
    
    /**
     * One destination's essentials and our eSIM plans there.
     */
    func destination(slug: String) async throws  -> DestinationDetail
    
    /**
     * Loads the destinations for the Explore tab.
     */
    func loadDestinations() async throws  -> Home
    
    /**
     * Loads the customer's saved trips.
     */
    func loadTrips() async throws  -> Home
    
    /**
     * Saves a trip to `destination_slug`. Dates are `YYYY-MM-DD`, each
     * optional; empty notes are dropped.
     */
    func saveTrip(destinationSlug: String, startDate: String?, endDate: String?, notes: String?) async throws  -> Home
    
    /**
     * Airports for the search forms.
     */
    func loadAirports() async throws  -> Airports
    
    /**
     * The cheapest estimated return from `from` to each destination
     * airport in `month` (`YYYY-MM`), cheapest first.
     */
    func priceMap(from: String, month: String) async throws  -> PriceMap
    
    /**
     * Estimated car hire at a destination airport.
     */
    func searchCars(city: String, pickUp: String, dropOff: String) async throws  -> CarResults
    
    /**
     * Estimated flights for `search`.
     */
    func searchFlights(search: FlightSearch) async throws  -> FlightResults
    
    /**
     * Estimated flight + hotel: the cheapest flight with each place to stay.
     */
    func searchPackages(from: String, to: String, depart: String, returnDate: String, adults: UInt32) async throws  -> PackageResults
    
    /**
     * Estimated places to stay in `city` (a destination airport code).
     */
    func searchStays(city: String, checkIn: String, checkOut: String, guests: UInt32, sort: StaySort) async throws  -> StayResults
    
    /**
     * Remembers where searches and the price map start from.
     */
    func setHomeAirport(code: String) async throws  -> Home
    
}
