    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Account {
        return
            try Account(
                username: FfiConverterString.read(from: &buf), 
                email: FfiConverterOptionString.read(from: &buf), 
                serverUrl: FfiConverterString.read(from: &buf)
        )
    }

    public static func write(_ value: Account, into buf: inout [UInt8]) {
        FfiConverterString.write(value.username, into: &buf)
        FfiConverterOptionString.write(value.email, into: &buf)
        FfiConverterString.write(value.serverUrl, into: &buf)
    }
}


